  Iu = `Tim Steam akan menghubungimu via tiket Bantuan Steamworks jika terdapat perubahan yang diperlukan untuk halamanmu. Lihat tiket Bantuan Steamworks, dan tambahkan komentar jika diperlukan dengan mengeklik tombol di sebelah kanan.`,
