  Uu = `Halaman diskon akan dikunci setelah ditinjau. Jika terdapat perubahan yang perlu dilakukan setelah peninjauan atau setelah event dimulai, silakan tulis di komentar tentang perubahan tersebut dan alasan mengapa itu tidak dapat diselesaikan sebelum peninjauan.`,
