  eU = `Tidak dapat membuka amplop`,
  tU = `PERLOMBAAN BESAR KAISAR`,
  nU = `Asal-Usul dari Zodiak Tionghoa`,
  rU = `Bagian I dari IV`,
  iU = `Bagian II dari IV`,
  aU = `Bagian III dari IV`,
  oU = `Bagian IV dari IV`,
  sU = `Kaisar Giok memanggil semua makhluk hidup di kerajaannya untuk berlomba mencapai kerajaan surga. Ia menyatakan bahwa 12 makhluk pertama yang sampai akan mendapatkan kehormatan untuk masuk dalam kalender baru yang ia buat.

Tikus yang Cerdas adalah yang pertama menyeberangi sungai menuju wilayah surga. Karena tidak bisa berenang, si Tikus menunggangi Kerbau—dengan semangat, ia melompat ke halaman sang Kaisar bahkan sebelum keduanya sampai ke tepi sungai.

Kerbau yang Tenang menyeberangi sungai dengan santai. Tidak peduli dengan hasil dari perlombaannya, si Kerbau senang dengan perannya di balik kesuksesan si Tikus.`,
  cU = `Harimau yang Mandiri melakukan perjalanan dengan sangat berhati-hati dan tidak mendahului si Kerbau. Lebih baik ada di urutan ketiga daripada tidak sampai sama sekali, pikirnya.

Kelinci yang Lincah melompat ke atas batang kayu yang mengapung entah ke mana. Strateginya kurang tepat, tetapi keberuntungan ada di pihaknya. Ia dibantu oleh angin yang mengarahkan kapalnya dengan selamat sampai tujuan.

Naga Terbang dapat merasakan orang lain yang sedang berada dalam kesulitan, termasuk si Kelinci. Ialah yang menghembuskan angin untuk si Kelinci. Kehormatan lebih penting daripada kemenangan, dan si Naga pun sampai dengan urutan nomor lima.`,
  lU = `Ular yang Licik tidak tertarik untuk berusaha terlalu keras, jadi ia diam-diam melilitkan tubuhnya di kuku depan uda.

Saat si Kuda berpacu menuju garis finis, si Ular melepaskan lilitannya dan membuat si Kuda kaget cukup lama yang memberinya waktu untuk meluncur ke urutan keenam—dengan si Kuda yang gelisah berlari di belakangnya.`,
  uU = `Kambing, Monyet, dan Ayam bekerja sama dan membiarkan Kambing menempati urutan kedelapan karena telah menjadi tulang punggung perjalanan mereka. Monyet yang Riang pun menyusul dan si Ayam berjalan menempati urutan kesepuluh—puas dengan urutannya yang adil.

Anjing yang Ceria lebih tertarik untuk bermain air dan merasa urutan kesebelas sudah cukup untuk kesenangan yang ia dapatkan.

Babi adalah yang terakhir sampai. Ia banyak berhenti untuk mengudap dan tidur—cukup bijaksana untuk mengerti bahwa setiap binatang punya waktunya sendiri untuk melayani sang Kaisar.`,
  dU = `Perubahan pada profil akan berlaku setelah ditinjau`,
  fU = `© %1$s Valve Corporation. Hak cipta dilindungi Undang-Undang. Semua merek dagang merupakan hak pemilik dari negara AS dan negara lainnya.`,
